"use client";

import React from "react";
import { motion, useReducedMotion } from "motion/react";
import { TrendingUp, TrendingDown, Target, ShieldCheck } from "lucide-react";
import { cn } from "@/lib/utils";

export interface CryptoUpDownTargetLineProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onDrag" | "onDragStart" | "onDragEnd" | "onAnimationStart"> {
  assetSymbol?: string;
  targetPrice?: number;
  currentPrice?: number;
  payoutMultiplier?: number;
  timeRemaining?: string;
}

export function CryptoUpDownTargetLine({
  assetSymbol = "SOL",
  targetPrice = 142.5,
  currentPrice = 142.85,
  payoutMultiplier = 1.95,
  timeRemaining = "03:45",
  className,
  ...props
}: CryptoUpDownTargetLineProps) {
  const reduceMotion = useReducedMotion();
  const isAbove = currentPrice >= targetPrice;
  const diffPercent = (((currentPrice - targetPrice) / targetPrice) * 100).toFixed(2);

  return (
    <motion.div
      data-slot="crypto-up-down-target-line"
      initial={reduceMotion ? { opacity: 1 } : { opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3 }}
      className={cn(
        "relative mx-auto flex w-full max-w-sm flex-col rounded-2xl bg-white dark:bg-zinc-900/90 p-5 shadow-xs border border-zinc-200/80 dark:border-zinc-800 font-sans select-none",
        className
      )}
      {...props}
    >
      {/* Header */}
      <div className="flex items-center justify-between pb-3.5 border-b border-zinc-100 dark:border-zinc-800/60">
        <div className="flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-xl bg-zinc-100 dark:bg-zinc-800 text-zinc-900 dark:text-zinc-100 font-bold text-xs">
            {assetSymbol}
          </div>
          <div>
            <div className="flex items-center gap-1.5">
              <span className="text-xs font-bold text-zinc-900 dark:text-zinc-100">{assetSymbol}/USD Options</span>
              <span className="inline-flex items-center gap-0.5 text-[10px] font-semibold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/50 px-1.5 py-0.5 rounded-md">
                <ShieldCheck className="h-3 w-3" /> Live
              </span>
            </div>
            <span className="text-[11px] font-medium text-zinc-400">Target Line Level</span>
          </div>
        </div>

        <div className="text-right font-mono">
          <span className="text-xs font-semibold text-zinc-400 block text-[10px] uppercase tracking-wider">Expires In</span>
          <span className="text-xs font-bold text-zinc-900 dark:text-zinc-100">{timeRemaining}</span>
        </div>
      </div>

      {/* Target Level Visual Track */}
      <div className="my-4 relative rounded-xl bg-zinc-50 dark:bg-zinc-950/60 p-3.5 border border-zinc-100 dark:border-zinc-800/80">
        <div className="flex items-center justify-between text-xs mb-2">
          <span className="inline-flex items-center gap-1 text-zinc-500 dark:text-zinc-400 font-medium">
            <Target className="h-3.5 w-3.5 text-blue-500" /> Target Strike:
            <strong className="font-mono text-zinc-900 dark:text-zinc-100">${targetPrice.toFixed(2)}</strong>
          </span>
          <span
            className={cn(
              "inline-flex items-center gap-1 font-mono font-bold text-xs px-2 py-0.5 rounded-full",
              isAbove
                ? "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400"
                : "bg-rose-500/10 text-rose-600 dark:text-rose-400"
            )}
          >
            {isAbove ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
            {isAbove ? `+${diffPercent}%` : `${diffPercent}%`}
          </span>
        </div>

        {/* Crisp Target Line Diagram */}
        <div className="relative h-16 w-full flex items-center justify-center my-1">
          <svg className="h-full w-full overflow-visible" viewBox="0 0 280 50">
            {/* Target dashed line */}
            <line
              x1="0"
              y1="25"
              x2="280"
              y2="25"
              stroke="#0066FF"
              strokeWidth="1.5"
              strokeDasharray="4 4"
              opacity="0.6"
            />
            <text x="5" y="18" fill="#0066FF" fontSize="9" fontWeight="700">
              TARGET THRESHOLD (${targetPrice.toFixed(2)})
            </text>

            {/* Current Price Dot & Line indicator */}
            <line
              x1="180"
              y1="25"
              x2="180"
              y2={isAbove ? 10 : 40}
              stroke={isAbove ? "#10B981" : "#F43F5E"}
              strokeWidth="1.5"
            />
            <circle
              cx="180"
              cy={isAbove ? 10 : 40}
              r="4.5"
              fill={isAbove ? "#10B981" : "#F43F5E"}
            />
            <text
              x="190"
              y={isAbove ? 13 : 43}
              fill={isAbove ? "#10B981" : "#F43F5E"}
              fontSize="10"
              fontWeight="800"
              fontFamily="monospace"
            >
              ${currentPrice.toFixed(2)}
            </text>
          </svg>
        </div>
      </div>

      {/* Footer Info */}
      <div className="flex items-center justify-between text-xs pt-1">
        <span className="text-zinc-500 dark:text-zinc-400 font-medium">Estimated Payout</span>
        <div className="flex items-center gap-1.5">
          <span className="font-mono font-bold text-zinc-900 dark:text-zinc-100">{payoutMultiplier}x</span>
          <span className="text-[10px] font-semibold text-sky-600 dark:text-sky-400 bg-sky-50 dark:bg-sky-950/60 px-1.5 py-0.5 rounded-md">
            +{(payoutMultiplier * 100 - 100).toFixed(0)}% ROI
          </span>
        </div>
      </div>
    </motion.div>
  );
}

export default CryptoUpDownTargetLine;
